import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import './helpers.ts'; // silences logging
import { calculateEta } from '../src/services/eta.ts';
import { Store } from '../src/store.ts';

// Staging has ~5k shipments. The list handler pages (default 50, max 500) and computes the ETA only
// for the returned page, so its cost must not grow with the dataset. ETAs are NOT cached (stale ETAs, QA Nov 2026).
describe('listing a 5k-shipment store', () => {
  const store = new Store();
  const carriers = ['ATP', 'DHL', 'DPD', 'GLS', 'UPS'] as const;
  for (let i = 0; i < 5000; i++) {
    const s = store.addShipment({
      trackingNumber: `T${i}`,
      carrier: carriers[i % 5],
      serviceLevel: 'standard',
      recipient: { name: 'A', street: 'B', zip: '1010', city: 'Wien', country: 'AT' },
    });
    store.addEvent(s.id, 'picked_up');
  }

  it('a default page (limit 50) with ETAs stays far below a request budget', () => {
    const start = performance.now();
    const page = store.listShipments({ limit: 50 });
    const etas = page.map((s) => calculateEta(s, store.eventsFor(s.id)));
    const ms = performance.now() - start;
    assert.equal(etas.length, 50);
    assert.ok(ms < 100, `took ${ms.toFixed(1)} ms`); // measured ~0.4 ms; generous to avoid flakiness
  });

  it('even the maximum page (500) with ETAs is fast', () => {
    const start = performance.now();
    const page = store.listShipments({ limit: 500 });
    for (const s of page) calculateEta(s, store.eventsFor(s.id));
    assert.ok(performance.now() - start < 250);
  });
});
EOF
